import{_ as l,W as o,s as p,u as r,ah as d,I as n,w as e,Z as a,A as i}from"./chunks/framework.Dx7wo2et.js";import"./chunks/theme.CjgFg8Ql.js";const k=JSON.parse('{"title":"如何在 Kali Linux 上安装 SSH 服务 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Kali Linux 上安装 SSH 服务 | LCTT (201702) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Kali Linux 上安装 SSH 服务 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Kali Linux 上安装 SSH 服务 | LCTT (201702) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201702/20170121 How to install SSH  secure shell  service on Kali Linux","title":"如何在 Kali Linux 上安装 SSH 服务","tag":"201702"},"relativePath":"201702/20170121 How to install SSH  secure shell  service on Kali Linux.md","filePath":"[post].md"}'),u={name:"201702/20170121 How to install SSH  secure shell  service on Kali Linux.md"};function c(h,s,g,S,b,v){const t=o("Link");return r(),p("div",null,[s[13]||(s[13]=d(`<h1 id="如何在-kali-linux-上安装-ssh-服务" tabindex="-1">如何在 Kali Linux 上安装 SSH 服务 <a class="header-anchor" href="#如何在-kali-linux-上安装-ssh-服务" aria-label="Permalink to 如何在 Kali Linux 上安装 SSH 服务">​</a></h1><h3 id="介绍" tabindex="-1">介绍 <a class="header-anchor" href="#介绍" aria-label="Permalink to 介绍">​</a></h3><p><strong>目的</strong></p><p>我们的目的是 Kali Linux 上安装 SSH（安全 shell）。</p><p><strong>要求</strong></p><p>你需要有特权访问你的 Kali Linux 安装或者 Live 系统。</p><p><strong>困难程度</strong></p><p>很容易！</p><p><strong>惯例</strong></p><ul><li><code>#</code> - 给定命令需要以 root 用户权限运行或者使用 <code>sudo</code> 命令</li><li><code>$</code> - 给定命令以常规权限用户运行</li></ul><h3 id="指导" tabindex="-1">指导 <a class="header-anchor" href="#指导" aria-label="Permalink to 指导">​</a></h3><p><strong>安装 SSH</strong></p><p>从终端使用 <code>apt-get</code> 命令安装 SSH 包：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># apt-get update</span></span>
<span class="line"><span># apt-get install ssh</span></span></code></pre></div><p><strong>启用和开始使用 SSH</strong></p><p>为了确保安全 shell 能够使用，在重启系统后使用 <code>systemctl</code> 命令来启用它：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># systemctl enable ssh</span></span></code></pre></div><p>在当前对话执行中使用 SSH:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># service ssh start</span></span></code></pre></div><p><strong>允许 SSH Root 访问</strong></p><p>默认情况下 SSH 不允许以 root 用户登录，因此将会出现下面的错误提示信息：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Permission denied, please try again.</span></span></code></pre></div><p>为了通过 SSH 进入你的 Kali Linux 系统，你可以有两个不同的选择。第一个选择是创建一个新的非特权用户然后使用它的身份来登录。第二个选择，你可以以 root 用户访问 SSH 。为了实现这件事，需要在SSH 配置文件 <code>/etc/ssh/sshd_config</code> 中插入下面这些行内容或对其进行编辑：</p><p>将</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#PermitRootLogin prohibit-password</span></span></code></pre></div><p>改为：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>PermitRootLogin yes</span></span></code></pre></div><p><img src="https://linuxconfig.org/images/enable-root-ssh-login-kali-linux.jpg" alt="kali linux enable ssh root access"></p><p>对 <code>/etc/ssh/sshd_config</code> 进行更改以后，需在以 root 用户登录 SSH 前重启 SSH 服务：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># service ssh restart</span></span></code></pre></div><hr>`,31)),n("p",null,[s[1]||(s[1]=e("via: ")),a(t,{href:"https://linuxconfig.org/how-to-install-ssh-secure-shell-service-on-kali-linux"},{default:i(()=>s[0]||(s[0]=[e("https://linuxconfig.org/how-to-install-ssh-secure-shell-service-on-kali-linux")])),_:1})]),n("p",null,[s[5]||(s[5]=e("作者：")),a(t,{href:"https://linuxconfig.org/how-to-install-ssh-secure-shell-service-on-kali-linux"},{default:i(()=>s[2]||(s[2]=[e("Lubos Rendek")])),_:1}),s[6]||(s[6]=e(" 译者：")),a(t,{href:"https://github.com/ucasFL"},{default:i(()=>s[3]||(s[3]=[e("ucasFL")])),_:1}),s[7]||(s[7]=e(" 校对：")),a(t,{href:"https://github.com/wxy"},{default:i(()=>s[4]||(s[4]=[e("wxy")])),_:1})]),n("p",null,[s[10]||(s[10]=e("本文由 ")),a(t,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>s[8]||(s[8]=[e("LCTT")])),_:1}),s[11]||(s[11]=e(" 原创编译，")),a(t,{href:"https://linux.cn/"},{default:i(()=>s[9]||(s[9]=[e("Linux中国")])),_:1}),s[12]||(s[12]=e(" 荣誉推出"))])])}const f=l(u,[["render",c]]);export{k as __pageData,f as default};
